from pathlib import Path
import fcntl,hashlib,json,subprocess,sys,time
root=Path.cwd();sys.path.insert(0,str(root/'tools'));from browser_bundle_lease import canonical_bundle_lease
out=root/'Build/site-opt2-20261108';state=root/'Build/production-build';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();sources={str(root/n):sha(root/n) for n in ['site_optimizations/animation_wakeups.v','site_optimizations/animation_clock_demand.v','css/animation_clock_demand.v','css/dom_css_bridge.v','html/event_loop.v','site_optimizations/stylesheet_layout.v','capture/ready_selector.v','fonts/font_resources.v','site_optimizations/raster_inputs.v','paint/stationary_raster.v']};deadline=time.monotonic()+2400;selected=None;release=None
while time.monotonic()<deadline:
 latest=state/'latest.json'
 try:
  r=json.loads(latest.read_text());f=json.loads(Path(r['frozen_compilation']).read_text());binary=Path(r['executable'])
  if f.get('complete') and all(f.get('exact_source_manifest',{}).get(p)==v for p,v in sources.items()):
   lease=canonical_bundle_lease(binary.parents[2]);lease.__enter__()
   if binary.is_file() and sha(binary)==r['executable_sha256']:
    selected=dict(receipt=str(Path(r['frozen_compilation']).parent),ready=r,frozen=f,canonical=True);release=lambda:lease.__exit__(None,None,None)
   else:lease.__exit__(None,None,None)
 except (OSError,ValueError,KeyError):pass
 if selected:break
 for receipt in sorted((state/'receipts').glob('20261108-*'),reverse=True):
  if not (receipt/'ready.json').exists() or (receipt/'result.json').exists():continue
  handle=None
  try:
   r=json.loads((receipt/'ready.json').read_text());f=json.loads((receipt/'frozen-compile.json').read_text());binary=Path(r['ready_executable'])
   if not f.get('complete') or any(f.get('exact_source_manifest',{}).get(p)!=v for p,v in sources.items()):continue
   handle=(receipt/'artifact.lock').open('a');fcntl.flock(handle,fcntl.LOCK_SH|fcntl.LOCK_NB)
   if not binary.is_file() or sha(binary)!=r['ready_executable_sha256']:handle.close();continue
  except (OSError,ValueError,KeyError):
   if handle:handle.close()
   continue
  selected=dict(receipt=str(receipt),ready=r,frozen=f,canonical=False);release=handle.close;break
 if selected:break
 time.sleep(.25)
if not selected:raise SystemExit('No completed production build contains the current clock policy')
(out/'completed-checks10-identity.json').write_text(json.dumps(selected,indent=2));print(json.dumps(dict(binary=str(binary),sha256=sha(binary),canonical=selected['canonical'])),flush=True);commands=[]
def run(name,template,extra=(),clock=False):
 script=Path('/tmp')/('vox-'+name+'-driver.py');text=(Path('/tmp')/template).read_text().replace("Path('Build/v/Vox.app/Contents/MacOS/Vox')",'Path('+repr(str(binary))+')')
 if clock:text=text.replace("root/'clock-observation-assets'","root/'clock-independent-assets'").replace('settle_seconds=8','settle_seconds=14')
 text=text.replace("VOX_DISABLE_GITHUB_IMAGE_LAYOUT_BATCHING='1',","VOX_DISABLE_GITHUB_RASTER_INPUT_REUSE='1',VOX_DISABLE_GITHUB_IMAGE_LAYOUT_BATCHING='1',")
 text=text.replace("VOX_GITHUB_IMAGE_LAYOUT_DIAGNOSTICS='1',","VOX_GITHUB_RASTER_INPUT_DIAGNOSTICS='1',VOX_STATIONARY_RASTER_DIAGNOSTICS='1',VOX_GITHUB_IMAGE_LAYOUT_DIAGNOSTICS='1',")
 text=text.replace("VOX_CAPTURE_DOCUMENT_ONLY='1',","VOX_CAPTURE_DOCUMENT_ONLY='1',VOX_CAPTURE_READY_SELECTOR='[data-testid=sponsor-button]:not([aria-disabled=\"true\"])',")
 text=text.replace("attributes=['aria-label']","attributes=['aria-label','aria-disabled','data-loading','disabled']")
 script.write_text(text);command=[sys.executable,str(script),'--name',name,*extra];r=subprocess.run(command);commands.append(dict(name=name,command=command,exit=r.returncode));return r.returncode==0
try:
 if not run('site10-diagnostic','vox-site3-wakeups-diagnostic.py',['--order','candidate','--diagnostic']):raise SystemExit(1)
 lines=(out/'site10-diagnostic/0-candidate.log').read_text().splitlines();eligibility=sum('Vox site animation wakeup: delay_ms=' in x for x in lines);demand=sum('Vox site animation demand: idle clock tick' in x for x in lines);print(json.dumps(dict(eligible_calls=eligibility,idle_clock_calls=demand,fallbacks=sorted(set(x for x in lines if 'Vox site animation wakeup: keep_ms=' in x))[:12])),flush=True)
 if not eligibility or not demand:raise SystemExit('Policy did not execute')
 if not run('site10-profile','vox-site3-wakeups-settle5-run.py',['--order','candidate','--sample']):raise SystemExit(1)
 if not run('site10-pilot','vox-site3-wakeups-settle5-run.py'):raise SystemExit(1)
 subprocess.run([sys.executable,'/tmp/vox-site10-verify-cohort.py',str(out/'site10-pilot')],check=True)
 if not run('site10-clock','vox-site3-clock-observation.py',clock=True):raise SystemExit(1)
 records=json.loads((out/'site10-clock/summary.json').read_text())['records'];checks=[]
 for record in records:
  s=next(x for x in record['audit']['selections'] if x['name']=='clock');samples=json.loads(s['elements'][0]['attributes']['data-vox-animation-clock-samples']);reference=samples[0];errors=[]
  for sample in samples[1:]:
   if not isinstance(sample['time'],(int,float)) or not isinstance(reference['time'],(int,float)):errors.append(None);continue
   delta=sample['time']-reference['time'];low=sample['begin']-reference['end'];high=sample['end']-reference['begin'];errors.append(max(0,low-delta,delta-high))
  checks.append(dict(kind=record['kind'],samples=samples,errors_ms=errors,valid=len(samples)==3 and all(e is not None and e<=100 for e in errors)))
 (out/'site10-clock/clock-verification.json').write_text(json.dumps(checks,indent=2));print(json.dumps(checks),flush=True)
 if not all(c['valid'] for c in checks if c['kind']=='candidate'):raise SystemExit('Clock verification did not pass')
 pilot=json.loads((out/'site10-pilot/verification.json').read_text())
 if not (pilot['valid'] and pilot['integer_20pct_gate']):raise SystemExit('Pilot does not qualify for acceptance')
 order=','.join(k for i in range(7) for k in (['control','candidate'] if i%2==0 else ['candidate','control']))
 name='site10-acceptance' if selected['canonical'] else 'site10-production-provisional'
 if not run(name,'vox-site3-wakeups-settle5-run.py',['--order',order]):raise SystemExit(1)
 subprocess.run([sys.executable,'/tmp/vox-site10-verify-cohort.py',str(out/name),'--acceptance'],check=True)
finally:
 (out/'completed-checks10-result.json').write_text(json.dumps(dict(identity=selected['ready'],canonical=selected['canonical'],commands=commands),indent=2));release()

