def primary(r):
 selections={v['name']:v for v in r['audit']['selections']}
 return {k:dict(count=selections[k]['count'],elements=[dict(attributes=e['attributes'],tag=e['tag'],text_sha256=e['text_sha256'],text_utf8_bytes=e['text_utf8_bytes']) for e in selections[k]['elements']]) for k in ['rows','file_links','readme','latest_commit','commit_links','buttons','images']}
for i,r in enumerate(records):
 audit=r['audit'];selections={v['name']:v for v in audit['selections']};img=Image.open(r['screenshot']).convert('RGBA');different=sum(1 for pixel in ImageChops.difference(reference_image,img).getdata() if pixel!=(0,0,0,0))
 checks.append(dict(index=i,kind=r['kind'],exit=r['exit'],ready=audit['ready'],url=audit['url'],fully_active=audit['fully_active'],native_errors=audit['native_reported_error_count'],javascript_diagnostics=audit['javascript_diagnostics'],viewport=[audit['viewport_width'],audit['viewport_height']],rows=selections['rows']['count'],file_links=selections['file_links']['count'],readme=selections['readme']['count'],latest_commit=selections['latest_commit']['count'],commit_links=selections['commit_links']['count'],deferred=selections['hydration']['count'],images=selections['images']['count'],primary_equal=primary(r)==primary(reference),different_pixels=different,png_sha256=hashlib.sha256(Path(r['screenshot']).read_bytes()).hexdigest()))
control=[r['instructions'] for r in records if r['kind']=='control'];candidate=[r['instructions'] for r in records if r['kind']=='candidate'];valid=d['identity_stable'] and all(c['exit']==0 and c['ready']=='complete' and c['fully_active'] and c['url']=='https://github.com/vlang/v' and c['native_errors']==0 and not c['javascript_diagnostics'] and c['viewport']==[1024,768] and c['rows']==33 and c['file_links']==141 and c['readme']==1 and c['latest_commit']==1 and c['commit_links']==53 and c['deferred']==0 and c['primary_equal'] and c['different_pixels']==0 for c in checks)
result=dict(controls=control,candidates=candidate,median_control=statistics.median(control),median_candidate=statistics.median(candidate),median_reduction=1-statistics.median(candidate)/statistics.median(control),conservative_reduction=1-max(candidate)/min(control),integer_20pct_gate=5*max(candidate)<=4*min(control),identity_stable=d['identity_stable'],valid=valid,checks=checks)
result['acceptance']=valid and len(control)>=7 and len(candidate)>=7 and result['integer_20pct_gate'] and all(records[i]['kind']!=records[i+1]['kind'] for i in range(0,len(records)-1,2))
(a.cohort/'verification.json').write_text(json.dumps(result,indent=2));print(json.dumps({k:v for k,v in result.items() if k!='checks'},indent=2));print('Per-run pixel differences:',[c['different_pixels'] for c in checks]);print('Per-run primary equality:',[c['primary_equal'] for c in checks])
if a.acceptance and not result['acceptance']:raise SystemExit(1)

